describe('Itemised Receipt After Checkout', () => {
  beforeEach(() => {
    cy.visit('/checkout');
  });

  it('should display an itemised receipt after successful checkout', () => {
    // Add items to cart
    cy.get('[data-testid="add-to-cart-btn"]').click();
    cy.get('[data-testid="add-to-cart-btn"]').click();
    cy.get('[data-testid="add-to-cart-btn"]').click();

    // Proceed to checkout
    cy.get('[data-testid="proceed-to-checkout-btn"]').click();

    // Fill in shipping details
    cy.get('[data-testid="shipping-address-input"]').type('123 Main St');
    cy.get('[data-testid="city-input"]').type('Anytown');
    cy.get('[data-testid="zip-code-input"]').type('12343');

    // Select shipping method
    cy.get('[data-testid="shipping-method-standard"]').click();

    // Proceed to payment
    cy.get('[data-testid="continue-to-payment-btn"]').click();

    // Fill in payment details
    cy.get('[data-testid="card-number-input"]').type('4111111111111111');
    cy.get('[data-testid="expiry-date-input"]').type('12/25');
    cy.get('[data-testid="cvv-input"]').type('123');

    // Complete checkout
    cy.get('[data-testid="place-order-btn"]').click();

    // Verify receipt is displayed
    cy.get('[data-testid="receipt-container"]').should('be.visible');
    cy.get('[data-testid="receipt-title"]').should('contain', 'Order Receipt');

    // Verify itemised list is present
    cy.get('[data-testid="receipt-item-row"]').should('have.length.greaterThan', 0);
    cy.get('[data-testid="receipt-item-row"]').first().should('contain', 'Product Name');
    cy.get('[data-testid="receipt-item-row"]').first().should('contain', '$19.99');

    // Verify total amount is displayed
    cy.get('[data-testid="receipt-total"]').should('be.visible');
    cy.get('[data-testid="receipt-total"]').should('contain', '$59.97');

    // Verify tax and shipping are itemised
    cy.get('[data-testid="receipt-tax-line"]').should('be.visible');
    cy.get('[data-testid="receipt-shipping-line"]').should('be.visible');
  });

  it('should handle empty cart and prevent receipt display', () => {
    // Attempt to proceed to checkout with empty cart
    cy.get('[data-testid="proceed-to-checkout-btn"]').click();

    // Verify error message is displayed
    cy.get('[data-testid="empty-cart-error"]').should('be.visible');
    cy.get('[data-testid="empty-cart-error"]').should('contain', 'Your cart is empty');

    // Verify receipt container does not appear
    cy.get('[data-testid="receipt-container"]').should('not.exist');

    // Verify user is redirected back to cart page
    cy.url().should('include', '/cart');
  });
});
